import{z as i,x as p,o as l,c as d,q as r,j as B,D as e,d as o,s as E,S as s,b as n}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"主定理","description":"","frontmatter":{"title":"主定理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/master-theorem.md","filePath":"cs/master-theorem.md","lastUpdated":1791063341000}'),f={name:"cs/master-theorem.md"};function A(T,a,h,b,g,_){const t=p("Mermaid");return l(),d("div",null,[a[2]||(a[2]=r('<h1 id="主定理" tabindex="-1">主定理 <a class="header-anchor" href="#主定理" aria-label="Permalink to &quot;主定理&quot;">​</a></h1><div class="epigraph"><p>形如 $T(n)=aT(n/b)+f(n)$ 的递归，其渐近由 $f$ 与 $n^{\\log_b a}$ 谁主谁从决定。</p><footer>—— 据 Bentley, Haken and Saxe, A General Method for Solving Divide-and-Conquer Recurrences, 1980；CLRS 第 4 章整理</footer></div><p>上一课<a href="/cs/loop-invariant">循环不变式</a>给了迭代过程的正确性骨架。<a href="/cs/loop-invariant">渐近记号</a>早已能写 \\(\\Theta\\)。本课不重证大 \\(O\\)，也不把递归树画成百科。缺口是：后课分治会留下 \\(T(n)=aT(n/b)+f(n)\\)，循环不变式推不出这根式子的阶。本课只钉主定理的三种情形，把分治范式本身留给下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>归并、二分、Strassen 乘法都把规模 \\(n\\) 切成 \\(a\\) 块、每块约 \\(n/b\\)，合并花 \\(f(n)\\)。递归树的层数是 \\(\\Theta(\\log_b n)\\)，叶子是 \\(n^{\\log_b a}\\)。总代价是根上的 \\(f\\)、中间层、叶子三者之一主导。没有比较 \\(f\\) 与 \\(n^{\\log_b a}\\) 的规则，每道题都要重画树。</p><p>缺口因此不是「递归是什么」，而是一条够用的判定：\\(f\\) 多项式地小于、等于、或大于叶子阶时，\\(T(n)\\) 分别是 \\(\\Theta(n^{\\log_b a})\\)、\\(\\Theta(n^{\\log_b a}\\log n)\\)、\\(\\Theta(f(n))\\)。规律性条件（对某个 \\(c\\lt 1\\) 有 \\(a f(n/b)\\le c f(n)\\)）管第三种，本课点名不展开证明。</p><h3 id="主定理不是所有递归" tabindex="-1">主定理不是所有递归 <a class="header-anchor" href="#主定理不是所有递归" aria-label="Permalink to &quot;主定理不是所有递归&quot;">​</a></h3><p>\\(T(n)=T(n-1)+\\Theta(n)\\) 不是等分，主定理不适用；那是等差求和。\\(T(n)=T(\\lfloor n/2\\rfloor)+T(\\lceil n/2\\rceil)+\\Theta(n)\\) 要地板函数引理，CLRS 用替换法补。本课默认 \\(n/b\\) 写法已经光滑。</p><p><span class="marginnote">Akra–Bazzi 处理不等分；本课不启用。Bentley–Haken–Saxe 的递归树是同一套几何级数比较。后课只引用三种情形的结论。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先算临界指数 \\(\\log_b a\\)。把 \\(f(n)\\) 与 \\(n^{\\log_b a}\\) 比多项式因子：若 \\(f=O(n^{\\log_b a-\\varepsilon})\\) 对某 \\(\\varepsilon\\gt 0\\)，叶子赢；若 \\(f=\\Theta(n^{\\log_b a})\\)，每层同阶，乘 \\(\\log n\\)；若 \\(f\\) 更大且规律，根上的 \\(f\\) 赢。</p><p><span class="marginnote">数字实例：归并排序 \\(T(n)=2T(n/2)+n\\)，先算 \\(\\log_2 2=1\\)；\\(f(n)=n=n^1\\) 与叶子同阶，落情形二，直接得 \\(\\Theta(n\\log n)\\)。拿到递归先代一次这个比值，就知道查哪一行，不必真画树。</span></p>',12)),(l(),B(s,null,{default:e(()=>[E(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20REC%5B%22T(n)%3Da%20T(n%2Fb)%2Bf(n)%22%5D%20--%3E%20CMP%5B%22%E6%AF%94%E8%BE%83%20f%20%E4%B8%8E%20n%5E%7Blog_b%20a%7D%22%5D%0A%20%20CMP%20--%3E%20C1%5B%22%E6%83%85%E5%BD%A2%E4%B8%80%EF%BC%9A%E5%8F%B6%E5%AD%90%E4%B8%BB%E5%AF%BC%22%5D%0A%20%20CMP%20--%3E%20C2%5B%22%E6%83%85%E5%BD%A2%E4%BA%8C%EF%BC%9A%E5%B1%82%E6%95%B0%E4%B9%98%E7%AD%89%E9%98%B6%22%5D%0A%20%20CMP%20--%3E%20C3%5B%22%E6%83%85%E5%BD%A2%E4%B8%89%EF%BC%9A%E5%90%88%E5%B9%B6%E4%B8%BB%E5%AF%BC%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n("p",null,"替换法仍是后盾：猜对阶再归纳。主定理只是常见等分的快捷方式。本课不把主定理证完；树的层和几何比在 CLRS 4.5–4.6。",-1)),a[4]||(a[4]=n("h2",{id:"机制",tabindex:"-1"},[o("机制 "),n("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=n("p",null,"有了三种情形，后课写归并 \\(T(n)=2T(n/2)+\\Theta(n)\\) 直接落在情形二，\\(\\Theta(n\\log n)\\)；二分查找 \\(T(n)=T(n/2)+\\Theta(1)\\) 是情形二的退化，\\(\\Theta(\\log n)\\)。正确性仍走递归假设或循环不变式，本课只管代价。",-1)),a[6]||(a[6]=n("p",null,"判断落在哪种情形之后，可以再问一句：递归树上各层的代价随深度怎么变？这决定总账记在哪一层。",-1)),(l(),B(s,null,{default:e(()=>[E(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%A0%B9%EF%BC%9A%E4%B8%80%E4%BB%BD%20f(n)%22%5D%20--%3E%20MID%5B%22%E4%B8%AD%E9%97%B4%E5%B1%82%EF%BC%9Aa%5Ej%20%E4%BB%BD%20f(n%2Fb%5Ej)%22%5D%0A%20%20MID%20--%3E%20LEAF%5B%22%E5%BA%95%E5%B1%82%EF%BC%9A%E7%BA%A6%20n%5E(log_b%20a)%20%E7%89%87%E5%8F%B6%E5%AD%90%22%5D%0A%20%20ROOT%20--%3E%20C3%5B%22%E5%90%88%E5%B9%B6%E4%B8%BB%E5%AF%BC%EF%BC%9A%E6%80%BB%E5%92%8C%E7%BA%A6%20f(n)%22%5D%0A%20%20MID%20--%3E%20C2%5B%22%E6%AF%8F%E5%B1%82%E5%90%8C%E9%98%B6%EF%BC%9A%E6%80%BB%E5%92%8C%E4%B9%98%20log%20n%22%5D%0A%20%20LEAF%20--%3E%20C1%5B%22%E5%8F%B6%E5%AD%90%E4%B8%BB%E5%AF%BC%EF%BC%9A%E6%80%BB%E5%92%8C%E7%BA%A6%20n%5E(log_b%20a)%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">直觉类比：把递归树想成一座金字塔——顶层是根上的合并费 \\(f(n)\\)，底层是 \\(n^{\\log_b a}\\) 片叶子。哪一层体积最大，总造价就记哪层的账；各层一样厚时，多出来的 \\(\\log n\\) 层数就是那个乘法因子。</span></p><p>不要把 \\(\\log\\) 底写进 \\(\\Theta\\)：底是常数。也不要把 \\(a\\)、\\(b\\) 当输入规模；它们是算法切法的参数。</p><p><span class="marginnote">常见误区：初学者见到 \\(\\log_2 n\\)、\\(\\log_{10} n\\) 想换算底数。由换底公式 \\(\\log_b n=\\log n/\\log b\\)，底只差常数倍，在 \\(\\Theta\\) 里被吞掉；真正改变阶的是 \\(a\\) 与 \\(b\\) 的组合，比如 \\(a\\) 翻一倍可能把阶抬高一整档。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>主定理不处理减而治之、不处理期望递归、不处理最坏与平均混写。快排的期望是<a href="/cs/quicksort-expected">后课</a>另开的指示器分析。不规则 \\(f\\)（在临界附近振荡）可以掉出三种情形，那时退回递归树或 Akra–Bazzi。</p><p>后课默认：看到等分递归，先套主定理再谈实现。分治作为设计法，下一课才命名。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>\\(T(n)=aT(n/b)+f(n)\\) 由 \\(f\\) 与 \\(n^{\\log_b a}\\) 的多项式比较分三种情形。</li><li>不是所有递归都能套；减一、不等分要另法。</li><li>本课只给阶，不给分治的正确性模板。</li><li>出处：Bentley, Haken and Saxe, 1980；CLRS 第 4 章。</li></ul>',8))])}const c=i(f,[["render",A]]);export{C as __pageData,c as default};
